begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);
grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('50000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'role','authenticated','session_id',pg_temp.i(n),'is_anonymous',false)::text,true)$$;
create function pg_temp.payload(n integer) returns jsonb language sql as $$select jsonb_build_object('version',1,'transactionId',pg_temp.i(n),'organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'deviceId',pg_temp.i(501),'cashierId',auth.uid(),'shiftId',(select id from public.cashier_shifts where cashier_id=auth.uid() and device_id=pg_temp.i(501) and closed_at is null),'occurredAt',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'total',75000,'cashReceived',100000,'items',jsonb_build_array(jsonb_build_object('productId',pg_temp.i(301),'unitId',pg_temp.i(401),'batchId',null,'name','Grower feeds','unitName','Sack','quantity','0.5','factor','50','unitPrice',150000,'unitCost',120000,'priceVersion',1,'lineTotal',75000)))$$;

create function pg_temp.ctx(b integer default 101) returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(b))$$;
create function pg_temp.transfer_receipt(q text default '30') returns jsonb language sql as $$select pg_temp.ctx(102)||jsonb_build_object('transferId',pg_temp.i(801),'receiptId',pg_temp.i(802),'quantity',q,'heldQuantity','10','reason','TEST physical count: 30 saleable, 10 damaged, 10 missing')$$;
create function pg_temp.stock(b integer default 101) returns text language sql as $$select quantity::text from public.branch_inventory where branch_id=pg_temp.i(b) and product_id=pg_temp.i(301) and batch_id is null$$;
create function pg_temp.plan(saleid integer default 701) returns jsonb language sql as $$select public.agri_command('partial_refund_plan',pg_temp.ctx()||jsonb_build_object('saleId',pg_temp.i(saleid)))$$;
create function pg_temp.refund(ident integer,q text default '0.2',t text default '0',d text default 'not_returned',saleid integer default 701) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('saleId',pg_temp.i(saleid),'refundId',pg_temp.i(ident),'shiftId',(select id from public.cashier_shifts where closed_at is null and branch_id=pg_temp.i(101)),'reference','TEST signed partial refund','reason','TEST inspected physical return and original cash amount','physicalConfirmed',true,'expectedRefundVersion',pg_temp.plan(saleid)->'version','expectedAmount',round((pg_temp.plan(saleid)->'lines'->0->>'lineTotal')::numeric*((pg_temp.plan(saleid)->'lines'->0->>'refundedQuantity')::numeric+q::numeric)/(pg_temp.plan(saleid)->'lines'->0->>'quantity')::numeric)::bigint-(pg_temp.plan(saleid)->'lines'->0->>'refundedAmount')::bigint,'items',jsonb_build_array(jsonb_build_object('lineIndex',0,'quantity',q,'returnedQuantity',t,'disposition',d)))$$;
create temporary table saved(name text primary key,data jsonb);grant all on saved to authenticated;
set local role authenticated;select pg_temp.login(11);
select public.agri_command('open_shift',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(501),'openingCash',10000));
select public.agri_command('record_sale',pg_temp.payload(701));
select public.agri_command('partial_refund_sale',pg_temp.refund(804,'0.3'));
select public.agri_command('record_sale',pg_temp.payload(702));
select public.agri_command('close_shift',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(501),'shiftId',(select id from public.cashier_shifts where closed_at is null),'countedCash',85000));
select public.agri_command('open_shift',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(501),'openingCash',0));
-- Rounding against an actual catalog price: 0.3 sack at 333 centavos costs 100 centavos.
select public.agri_command('set_price',pg_temp.ctx()||jsonb_build_object('unitId',pg_temp.i(401),'price',333,'cost',100,'reason','TEST centavo allocation fixture'));
select public.agri_command('record_sale',pg_temp.payload(703)||jsonb_build_object('total',100,'cashReceived',100,'items',jsonb_build_array((pg_temp.payload(703)->'items'->0)||'{"quantity":"0.3","unitPrice":333,"unitCost":100,"priceVersion":2,"lineTotal":100}')));
select public.agri_command('partial_refund_sale',pg_temp.refund(810,'0.1','0','not_returned',703));
select public.agri_command('partial_refund_sale',pg_temp.refund(811,'0.1','0','not_returned',703));
select public.agri_command('partial_refund_sale',pg_temp.refund(812,'0.1','0','not_returned',703));
select public.agri_command('set_price',pg_temp.ctx()||jsonb_build_object('unitId',pg_temp.i(401),'price',150000,'cost',120000,'reason','TEST restore catalog price'));
-- Invalid/multiple lines roll back as one request, with no cash or stock leakage.
-- Thirty-one tiny portions allocate no cent yet, and history remains paginated.
select public.agri_command('set_price',pg_temp.ctx()||jsonb_build_object('unitId',pg_temp.i(401),'price',1,'cost',0,'reason','TEST tiny allocations'));
select public.agri_command('record_sale',pg_temp.payload(704)||jsonb_build_object('total',1,'cashReceived',1,'items',jsonb_build_array((pg_temp.payload(704)->'items'->0)||'{"quantity":"1","unitPrice":1,"unitCost":0,"priceVersion":4,"lineTotal":1}')));
do $$begin for n in 1..31 loop perform public.agri_command('partial_refund_sale',pg_temp.refund(900+n,'0.01','0','not_returned',704));end loop;end$$;
select public.agri_command('partial_refund_sale',pg_temp.refund(950,'0.69','0','not_returned',704));
-- Physical controls cover whole pieces, multiple original lines and lots that expire after sale.
reset role;
set local role authenticated;select pg_temp.login(11);
select public.agri_command('record_sale',pg_temp.payload(705)||jsonb_build_object('total',75200,'cashReceived',75200,'items',(pg_temp.payload(705)->'items')||jsonb_build_array(jsonb_build_object('productId',pg_temp.i(303),'unitId',pg_temp.i(403),'batchId',null,'name','TEST seed packets','unitName','Packet','quantity','2','factor','1','unitPrice',100,'unitCost',50,'priceVersion',1,'lineTotal',200))));
reset role;
set local role authenticated;select pg_temp.login(11);
select public.agri_command('record_sale',pg_temp.payload(706)||jsonb_build_object('items',jsonb_build_array((pg_temp.payload(706)->'items'->0)||jsonb_build_object('batchId',pg_temp.i(621)))));
reset role;update public.product_batches set expires_on=current_date-1 where id=pg_temp.i(621);
set local role authenticated;select pg_temp.login(11);
select pg_temp.login(12);
select pg_temp.login(13);
select pg_temp.login(14);
select pg_temp.login(15);
select pg_temp.login(11);
reset role;
update auth.sessions set not_after=now()-interval '1 second' where user_id=pg_temp.i(11);
set local role authenticated;select pg_temp.login(11);
reset role;
select line from tap_results;
select * from finish();
rollback;
